// src/app/helpers/constants/constants.ts
var Constant = {
  ACCESS_TOKEN: "access_token",
  REFRESH_TOKEN: "refresh_token",
  USERNAME: "username"
};

// src/app/helpers/interceptors/authentication.interceptor.ts
var authenticationInterceptor = (req, next) => {
  const ACCESS_TOKEN = localStorage.getItem(Constant.ACCESS_TOKEN);
  if (ACCESS_TOKEN) {
    const AUTH_REQUEST = req.clone({
      setHeaders: {
        Authorization: `Bearer ${ACCESS_TOKEN}`
      }
    });
    return next(AUTH_REQUEST);
  }
  return next(req);
};

// src/main.ts
bootstrapApplication(AppComponent, {
  providers: [
    provideRouter(routes),
    provideHttpClient(withInterceptors([authenticationInterceptor])),
    provideAnimations()
  ]
});
